const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const rawBody = item.json.rawBody || JSON.stringify(item.json.body || {});

const eventId = headers['x-event-id'];
const timestampStr = headers['x-timestamp'];
const signature = headers['x-signature'];

if (!signature || !timestampStr || !eventId) {
  throw new Error('Missing required webhook verification headers');
}

const timestamp = parseInt(timestampStr, 10);
const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - timestamp) > 300) {
  throw new Error('Timestamp skew exceeds 300 seconds');
}

const secret = $env.N8N_EVENT_SIGNING_SECRET || '';
const canonical = timestampStr + '.' + rawBody;
const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');

if (signature !== expectedSig) {
  throw new Error('Invalid X-Signature');
}

const parsed = typeof item.json.body === 'object' ? item.json.body : JSON.parse(rawBody);
const payload = parsed.payload || {};
const leadId = payload.lead_id || parsed.aggregate_id;

return [{
  json: {
    event_id: eventId,
    event_type: parsed.event_type,
    tenant_id: parsed.tenant_id,
    lead_id: leadId,
    conversation_id: payload.conversation_id,
    message_id: payload.message_id,
    occurred_at: parsed.occurred_at
  }
}];

const leadResp = $input.first().json || {};
const lead = leadResp.data || {};
const event = $('Verify Dispatcher Signature').item.json;

const assignedUserId = lead.assigned_user_id;
const managerUserIds = lead.manager_user_ids || [];
const leadName = lead.name || 'Unknown';

const notifications = [];
if (assignedUserId) {
  notifications.push({
    user_id: assignedUserId,
    title: 'Customer Replied: ' + leadName,
    body: 'Customer ' + leadName + ' replied to your message.',
    idempotency_key: event.event_id + '-notif'
  });
} else {
  for (let i = 0; i < managerUserIds.length; i++) {
    const mgrId = managerUserIds[i];
    notifications.push({
      user_id: mgrId,
      title: 'Customer Replied: ' + leadName,
      body: 'Unassigned lead ' + leadName + ' replied to message.',
      idempotency_key: event.event_id + '-notif-' + mgrId
    });
  }
}

return [{
  json: {
    event_id: event.event_id,
    tenant_id: event.tenant_id,
    lead_id: event.lead_id,
    notifications: notifications,
    has_notifications: notifications.length > 0,
    first_notification: notifications.length > 0 ? notifications[0] : null
  }
}];
